INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65704877', 65704877, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Belanja Jasa Sertifikasi Data Analis pada Direktorat Teknologi Informasi, Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 250000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Penyelenggaraan asesmen kompetensi bagi personel di bidang analisis data guna memvalidasi kemampuan teknis dalam pengolahan dan interpretasi data secara profesional. Lingkup kegiatan meliputi pendaftaran peserta, penyediaan modul persiapan, pelaksanaan ujian sertifikasi oleh lembaga berwenang, hingga penerbitan sertifikat keahlian yang diakui secara resmi sebagai standar kemampuan profesional.', 'Wajib memiliki akreditasi resmi sebagai lembaga sertifikasi profesi bidang teknologi informasi atau data science dengan penguji yang kompeten dan berpengalaman. Penyedia harus menjamin ketersediaan platform ujian yang transparan serta memberikan sertifikat yang dapat diverifikasi keasliannya melalui pangkalan data resmi lembaga sertifikasi terkait.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2312048);
