INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65705077', 65705077, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'PELABUHAN PERIKANAN NUSANTARA PENGAMBENGAN', 'Pemeliharaan jalan khusus kompleks', 'Barang', 'Pengadaan Langsung', 'Bali, Jembrana (Kab.)', 24940000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Jalan khusus komplek ( 172, M2, @ 145000 );', 'Teknis yang disesuaikan untuk proyek Pemeliharaan Jalan Khusus Kompleks PPN Pengambengan TA 2026, khususnya pada area perkantoran: 1. Pekerjaan Tanah dan Pondasi spesifikasi teknis meliputi: • Galian Tanah: Penggalian dilakukan untuk pemulihan kondisi, beton pengancing, dan pondasi sesuai dimensi gambar rencana. Tanah hasil galian yang tidak terpakai harus dibuang ke luar area kerja. • Urugan Pasir: Pasir urug harus bersih dari kotoran organik dan dipadatkan dengan ketebalan sesuai rencana sebagai dasar pondasi atau lantai. • Aanstamping (Pas. Batu Kosong): Menggunakan batu kali/gunung yang disusun tegak, rapat, dan diisi pasir di sela-selanya sebagai drainase bawah pondasi. • Pondasi Batu Kali 1 : 5: Menggunakan batu kali yang keras dan tidak keropos. Adukan semen (PC) dan pasir harus memiliki perbandingan volume 1 Semen : 5 Pasir. • Urugan Tanah Pilihan: Digunakan untuk mencapai elevasi yang diinginkan. Tanah harus bebas dari sisa akar dan sampah, serta dipadatkan per lapis (maksimal 20 cm per lapis). 2. Pekerjaan Paving Block (Sisi Utara & Selatan Kantor) • Pola Pasang: Pola harus seragam antara sisi utara dan selatan, disarankan pola Herringbone (Tulang Ikan) untuk penguncian yang maksimal. • Pasir Alas: Menggunakan pasir pasang setebal 3-5 cm sebagai landasan paving sebelum dipadatkan menggunakan Plate Compactor. 3. Pekerjaan Beton Pengancing & Rabat • Beton Pengancing: Berfungsi untuk menjepit susunan paving agar tidak bergeser. Dilaksanakan dengan pemasangan Begisting yang kokoh sebelum penuangan beton. • Beton Rabat: Lantai kerja atau perkerasan beton non-struktural sebagai dasar atau area sirkulasi pejalan kaki, dengan permukaan yang diratakan (finish trowel atau sapu). 4. Pekerjaan Arsitektural (Lantai Perkantoran) • Pasangan Keramik: Menggunakan keramik ukuran 40 x 40 cm berwarna Putih. • Kualitas: Keramik harus KW1, tidak retak, dan memiliki sudut yang presisi. • Metode Pasang: Nat keramik harus lurus dan diisi dengan semen warna (grout) yang senada. Permukaan harus rata dan memiliki kemiringan yang cukup ke arah pembuangan jika berada di area terbuka (teras).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2312972);
