INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65705982', 65705982, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Tenaga Alih Daya Staff Administrasi National Urban Flood Resilience Project (NUFRep) Direktorat Sumber Daya Air', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 122600000, 'February 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '11', '9. Ruang lingkup pekerjaan Tenaga Alih Daya Staf Administrasi NUFREP adalah mendukung tim sekretariat dalam bidang keuangan dengan rincian sebagai berikut: a. Membantu proses penyusunan dan penyesuaian Rencana Anggaran Biaya (RAB) tahunan berdasarkan kebutuhan kegiatan Tim Sekretariat NSCWR; b. Menyusun dan memperbarui laporan realisasi anggaran dan arus kas (cash flow) secara periodik, serta memastikan konsistensi dan kelengkapan data keuangan; c. Melakukan penataan, pengumpulan, dan pengarsipan seluruh dokumen pertanggungjawaban keuangan, baik dalam bentuk fisik maupun digital; d. Melakukan pengecekan dan verifikasi teknis atas kelengkapan dokumen pengajuan pembayaran atau pencairan dana sebelum diteruskan ke PPK; e. Mendukung pengelolaan aspek keuangan dalam pelaksanaan rapat, workshop, FGD, dan perjalanan dinas, termasuk penyiapan bukti pertanggungjawaban keuangan; f. Melaksanakan koordinasi dan komunikasi teknis terkait keuangan dengan PPK, bagian keuangan internal Bappenas; g. Melakukan input, pembaruan, dan rekonsiliasi data keuangan dalam sistem pelaporan proyek. h. Menjalankan penugasan lain dari Direktorat Sumber Daya Air Kementerian PPN/Bappenas terkait pelaksanaan fungsi administrasi keuangan proyek.', '12. Kualifikasi Penyedia jasa yang diharapkan adalah sebagai berikut : a. Berbentuk koperasi/badan usaha b. Memiliki izin usaha bidang jasa manajemen alih daya/perorangan c. Memiliki pengalaman penyediaan dan pengelolaan jasa alih daya tenaga perorangan 13. Kualfikasi Tenaga Alih Daya Staf Administrasi NUFREP adalah sebagai berikut. a. Minimal Pendidikan S1 di bidang akuntansi, keuangan, administrasi, dan ekonomi; b. Pengalaman minimal 5 tahun di bidang administrasi keuangan; c. Pengalaman minimal 2 tahun di bidang administrasi keuangan pada kegiatan/proyek/program bidang sumber daya air yang dibiayai Pinjaman Hibah Luar Negeri (PHLN); d. Pengalaman berkoordinasi dengan Kementerian Keuangan dalam rangka pengelolaan administrasi keuangan; e. Memiliki pengalaman bekerja sama dengan instansi Pemerintah Pusat dan Pemerintah Daerah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2314074);
