INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65708500', 65708500, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'PENYUSUNAN RENCANA AKSI PENANGANAN BANJIR DAN GENANGAN', 'Jasa Konsultansi', 'Seleksi', 'Banten, Tangerang (Kota)', 245267600, 'March 2026', 'APBD', 1, 1, '1', 'a. Menyusun Rencana Survei dan Investigasi Luasan Banjir, Drainase serta Bangunan Pengendali Banjir lainnya sesuai Kerangka Acuan Kerja. b. Memeriksa data hasil survei dan hasil pengumpulan data/informasi yang diperlukan untuk pemetaan deliniasi banjir. c. Menyusun pekerjaan persiapan d. Melaksanakan survei awal e. Mempelajari dan menguasai data terdahulu untuk daerah yang akan diselidiki. f. Mengintegrasikan database sungai/kali/saluran dengan program GIS. g. Melakukan pengarahan dan pemeriksaan pemetaan deliniasi banjir. h. Menyiapkan data hidrologi. i. Melakukan analisis menggunakan program aplikasi yang mampu melakukan analisa hidrologi dan hidrolika secara 2 Dimensi dan membuat peta banjir / flood map. j. Analisis menghasilkan simulasi banjir dengan memperhitungkan catchment area dan beberapa variasi Q hujan rencana serta beberapa alternatif penyusunan pompa atau bangunan pengendali banjir lainnya. k. Banyaknya alternatif / kondisi yang dilakukan dalam simulasi ditentukan pada saat proses pembahasan. l. Membuat laporan dan rekomendasi hasil perhitungan hidrologi dan hidrolika. m. Menyusun Rencana teknis pekerjaan drainase dan bangunan pengendali banjir lainnya. n. Memetakan Hasil Rencana Aksi Kegiatan dengan Software Berbasis GIS.', 'a. Ahli Madya S1 Pengalaman 1 Tahun (1 Orang) b. Ahli Muda S1 Pengalaman 2 Tahun (1 Orang) c. Tenaga Pendukung Operator SIG (3 Orang) d. Tenaga Pendukung Administrator (1 Orang)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2315443);
