INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65710112', 65710112, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Belanja Jasa Security Certification pada Direktorat Teknologi Informasi, Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 300000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Kegiatan ini melibatkan proses validasi keahlian teknis dalam mengamankan aset informasi dan infrastruktur digital organisasi dari berbagai potensi ancaman serta serangan siber. Lingkup pekerjaan mencakup tahap persiapan, simulasi pengamanan, serta pelaksanaan ujian sertifikasi yang berfokus pada aspek perlindungan data, manajemen risiko keamanan informasi, dan prosedur respons cepat terhadap insiden siber yang mungkin terjadi.', 'Penyedia jasa harus terafiliasi dengan badan sertifikasi keamanan informasi internasional yang diakui secara luas di industri teknologi global guna menjamin validitas sertifikat. Spesifikasi teknis menuntut penyedia mampu menyediakan kurikulum pengujian mutakhir sesuai perkembangan ancaman terbaru serta prosedur penilaian objektif yang didukung oleh penerbitan sertifikat berstandar keamanan tinggi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2315686);
