INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65708273', 65708273, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Tenaga Alih Daya Pengemudi National Urban Flood Resilience Project (NUFRep) Direktorat Sumber Daya Air', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 87890000, 'February 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '11', 'Ruang lingkup pekerjaan Tenaga Alih Daya Pengemudi NUFREP adalah mendukung tim sekretariat dalam bidang keuangan dengan rincian sebagai berikut: Melaksanakan layanan transportasi untuk mendukung mobilitas personel CPIU Bappenas dalam kegiatan administrasi, koordinasi, dan kegiatan lapangan proyek NUFReP. Melakukan pengantaran dan pengambilan surat, dokumen, serta perlengkapan/logistik kegiatan yang diperlukan untuk mendukung kelancaran pelaksanaan kegiatan proyek. Mendukung mobilisasi tim dan logistik dalam pelaksanaan rapat, workshop, kunjungan lapangan, dan kegiatan operasional lainnya sesuai kebutuhan proyek. Menjaga kesiapan, kebersihan, dan keamanan kendaraan yang digunakan selama masa penugasan agar selalu dalam kondisi baik. Melaksanakan penugasan operasional lain yang relevan dan diberikan oleh CPIU Bappenas sepanjang berkaitan dengan layanan transportasi dan bersifat pendukung', 'Kualifikasi Penyedia jasa yang diharapkan adalah sebagai berikut : Berbentuk koperasi/badan usaha Memiliki izin usaha bidang jasa manajemen alih daya/perorangan Memiliki pengalaman penyediaan dan pengelolaan jasa alih daya tenaga perorangan Kualfikasi Tenaga Alih Daya Staf Administrasi NUFREP adalah sebagai berikut. Minimal memiliki latar belakang pendidikan SMA/SMK Sederajat; Memiliki sedikitnya 1 (satu) tahun pengalaman kerja profesional; Memiliki kontrak kegiatan yang serupa dalam 10 (sepuluh) tahun terakhir minimal 50% dari nilai HPS.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2315808);
