INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65709003', 65709003, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'Satker MWA MCAI II', 'Jasa Konsultan Penyusunan Dokumen Pengelolaan dan Pengawasan Hibah Compact II', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 580000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Keg, @ 580000000 )', '1. Memberikan rekomendasi periodik dari perkembangan penyelarasan program Compact kepada Satker MWA MCA-I II sebagai Unit Pendukung KPA dibawah arahan Kementerian PPN/Bappenas, yang menjalankan fungsi pemantauan dan pengelolaan hibah Compact II baik secara administratif maupun substansif; 2. Bersama dengan seluruh konsultan Satker MWA MCA-I II dan UPP MCA-I II, melakukan identifikasi dan analisis terhadap kinerja pengembangan desain realignment program utama Compact II, yakni proyek infrastruktur baru dan pembiayaan UMKM yang mencakup kajian tim due diligence MCC, negosaisai dan persiapan amandemen perjanjian hibah, rencana kegiatan, estimasi anggaran, pemantauan kinerja konsultan pelaksana, pelaporan kegiatan dan persyaratan-persyaratan terkait hibah;', 'A. Persyaratan Administrasi 1. Berstatus sebagai Warga Negara Indonesia dibuktikan dengan Kartu Tanda Penduduk (KTP) atau Paspor 2. Memiliki Nomor Pokok Wajib Pajak (NPWP); 3. Mempunyai status valid keterangan Wajib Pajak berdasarkan hasil Konfimasi Status Wajib Pajak (KSWP); 4. Menyetujui Surat Pernyataan Peserta yang berisi: a. Tidak dikenai daftar hitam b. Keikutsertaannya tidak menimbulkan pertentangan kepentingan pihak yang terkait c. Tidak dalam pengawasan pengadilan dan/atau sedang menjalani sanksi pidana; dan d. Tidak berstatus ASN, kecuali bersangkutan mengambil cuti diluar tanggungan Negara. 1. Latar belakang pendidikan minimal S2 (Magister) dari institusi terakreditasi baik dalam maupun luar negeri bidang Manajemen, Teknik, atau Sains dibuktikan dengan Ijazah; 2. Memiliki pengalaman kerja professional minimal 16 tahun di bidang perencanaan dan pembiayaan infrastruktur publik, pengelolaan dan manajemen sumberdaya alam/lingkungan, atau perencanaan pembiayaan UMKM yang dibiayai dari hibah, pinjaman luar negeri, Pemerintah atau sektor swasta; yang dibuktikan dengan kontrak atau referensi dari pekerjaan sebelumnya;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2317538);
