INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65709987', 65709987, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Belanja Jasa COBIT Foundation pada Direktorat Teknologi Informasi, Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 300000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Penyediaan pelatihan dan ujian sertifikasi tingkat dasar untuk kerangka kerja COBIT guna meningkatkan pemahaman personel mengenai tata kelola TI organisasi secara global. Uraian tugas meliputi pemberian materi pelatihan mengenai prinsip utama tata kelola serta penyelenggaraan ujian resmi untuk mendapatkan gelar sertifikasi Foundation sebagai bukti penguasaan dasar tata kelola dan manajemen teknologi informasi.', 'Penyedia harus merupakan mitra pelatihan resmi (Authorized Training Partner) yang memiliki lisensi dari organisasi pemilik sertifikasi dengan instruktur yang memegang lisensi mengajar resmi. Fasilitas yang disediakan wajib mencakup akses ke materi pembelajaran asli, voucher ujian resmi, serta lingkungan ujian yang memenuhi standar keamanan pengujian internasional yang ketat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2317723);
