INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65710239', 65710239, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Belanja Jasa Certified Artificial Intelligence Practitioner (CAIP) pada Direktorat Teknologi Informasi, Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 700000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '2 Paket', 'Sertifikasi ini diarahkan pada tingkat praktisi bagi personel yang bekerja dengan teknologi kecerdasan buatan termasuk implementasi machine learning dalam berbagai solusi bisnis dan layanan publik. Pekerjaan mencakup verifikasi kemampuan merancang algoritma AI, pengelolaan dataset, serta penerapan solusi bertenaga AI secara efisien yang diakhiri dengan evaluasi teknis secara mendalam guna memastikan penguasaan teknologi otomasi terkini.', 'Lembaga penyedia wajib memiliki rekam jejak dalam penyelenggaraan sertifikasi AI yang bersifat vendor-neutral dengan tim penguji yang memiliki latar belakang praktis kuat di bidang kecerdasan buatan. Persyaratan teknis mencakup ketersediaan akses ke lingkungan pengembangan (sandbox) untuk ujian praktis serta kurikulum yang mencakup aspek etika dan keamanan dalam penggunaan teknologi kecerdasan buatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2318171);
