INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65708791', 65708791, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Tenaga Alih Daya Staf Pengelola Pinjaman National Urban Flood Resilience Project (NUFRep) Direktorat Sumber Daya Air', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 110316000, 'February 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '11', 'Ruang lingkup pekerjaan Tenaga Alih Daya Staf Pengelola Pinjaman NUFReP adalah mendukung tim sekretariat dalam bidang administrasi dengan rincian sebagai berikut : Melakukan pengarsipan, penyimpanan, dan pengelolaan surat, dokumen, data, dan informasi; Koordinasi dan komunikasi dengan Project Management Consultant, PPK, Pejabat Pengadaan terkait dalam mendukung proses pembuatan dokumen dan dokumentasi pengadaan barang dan jasa, serta persiapan kontrak; Menyusun berkas kelengkapan administrasi untuk pengajuan pencairan anggaran kegiatan NUFReP; Melakukan review kelengkapan dokumen administrasi keuangan untuk pengajuan pencairan pembayaran sebelum disampaikan ke PPK; Mendukung secara teknis dan administrasi dalam persiapan dan pelaksanaan kegiatan rapat/wokshop/FGD dan perjalanan dinas; Melaksanakan penugasan lain dari Project Management, konsultan, dan Direktorat Sumber Daya Air Kementerian PPN/Bappenas;', '12. Kualifikasi Penyedia jasa yang diharapkan adalah sebagai berikut : a. Berbentuk koperasi/badan usaha b. Memiliki izin usaha bidang jasa manajemen alih daya/perorangan c. Memiliki pengalaman penyediaan dan pengelolaan jasa alih daya tenaga perorangan 13. Kualfikasi Tenaga Alih Daya Staf Administrasi NUFREP adalah sebagai berikut. a. Minimal Pendidikan S1 di bidang akuntansi, keuangan, administrasi, dan ekonomi; b. Pengalaman minimal 5 tahun di bidang administrasi keuangan; c. Pengalaman minimal 2 tahun di bidang administrasi keuangan pada kegiatan/proyek/program bidang sumber daya air yang dibiayai Pinjaman Hibah Luar Negeri (PHLN); d. Pengalaman berkoordinasi dengan Kementerian Keuangan dalam rangka pengelolaan administrasi keuangan; e. Memiliki pengalaman bekerja sama dengan instansi Pemerintah Pusat dan Pemerintah Daerah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2319016);
