INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65707551', 65707551, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Tenaga Alih Daya Operasional National Urban Flood Resilience Project (NUFRep) Direktorat Sumber Daya Air', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 110316000, 'February 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '11', 'Lingkup Kerja Tenaga Alih Daya Operasional Kegiatan Flood Management in North Java Project (FMNJP) adalah sebagai berikut: Menangani kegiatan surat-menyurat, pencatatan, dan pendistribusian dokumen proyek; Menyiapkan dan mengelola dokumen administrasi untuk kegiatan pengadaan, pelaporan, serta korespondensi resmi; Membantu penyusunan daftar hadir, notulensi, laporan hasil kegiatan, serta dokumentasi rapat dan workshop; Melaksanakan pengarsipan berkas kegiatan secara terstruktur, baik dalam bentuk fisik (hardcopy) maupun digital (softcopy), termasuk pengelolaan sistem penamaan berkas dan penyimpanan dalam media yang aman; Mengatur kebutuhan logistik kegiatan sekretariat, perlengkapan kantor, dan perjalanan dinas CPIU; Mendukung pengelolaan jadwal dan administrasi kegiatan sekretariat CPIU; Mendukung proses koordinasi administratif lintas unit dan membantu penyusunan laporan berkala; Melaksanakan tugas lain yang relevan berdasarkan kebutuhan dari Direktorat Sumber Daya Air, Bappenas yang mendukung dalam pencapaian target pengelolaan Pantura Jawa yang terintegrasi dan outcome proyek.', 'Kualifikasi Penyedia jasa yang diharapkan adalah sebagai berikut : Berbentuk koperasi/badan usaha Memiliki izin usaha bidang jasa manajemen alih daya/perorangan Memiliki pengalaman penyediaan dan pengelolaan jasa alih daya tenaga perorangan Kualifikasi Tenaga Alih Daya Operasional Kegiatan FMNJP adalah sebagai berikut: Minimal memiliki latar belakang pendidikan Sarjana (S1) semua jurusan; Memiliki sedikitnya 3 (tiga) tahun pengalaman kerja profesional; Memiliki pengalaman kerja di bidang administrasi sedikitnya 1 (satu) tahun; Memiliki sedikitnya 1 (satu) pengalaman pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintahan maupun swasta; Memiliki pengalaman kerja dalam proyek sumber daya air yang didanai oleh lembaga/institusi/organisasi internasional; Memiliki kemampuan mengoperasikan perangkat lunak Excel; Memiliki kontrak kegiatan dalam kurun waktu 10 (sepuluh) tahun terakhir minimal 50% dari nilai HPS.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2319111);
