INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65710953', 65710953, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL ADMINISTRASI HUKUM UMUM', 'Pengadaan Belanja Jasa Konsultan Kegiatan Pemeliharaan Aplikasi AHU Online pada Direktorat Teknologi Informasi, Direktorat Jenderal Administrasi Hukum Umum Tahun Anggaran 2026', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 4890000000, 'January 2026', 'APBN - PNBP (D)', 0, 1, '1 Paket', 'Melakukan penyusunan program mutu pelaksanaan kegiatan yang setidaknya mencakup 1) Rencana Kerja yang terdiri dari a) Aktifitas pekerjaan b) Utilisasi tim pelaksana pekerjaan sesuai dengan ruang lingkup 2) Hasil asesmen kondisi aplikasi AHU Online saat ini 3) Menyusun ketentuan SOP terkait pelaksanaan pemeliharaan aplikasi (Pemeliharaan Konstruktif, Preventif, Korektif, Adaptif, Perfektif) 4) Menyusun dokumen standar pelaksanaan pengembangan dan pembangunan aplikasi dengan metode Software Development Life Cycle dan dokumen pendukungnya, sekurang-kurangnya terdiri dari proses Analisis Kebutuhan Aplikasi, Perancangan Aplikasi, Coding Aplikasi, Pengujian Aplikasi, Implementasi Aplikasi, Tinjauan pasca Implementasi Aplikasi 5) Menyusun dokumen standar pelaksanaan pengembangan dan pembangunan aplikasi dengan metode DevOps dan dokumen pendukungnya, sekurang-kurangnya terdiri dari Continuous Development, Continuous Testing, Continuous Integration, Continuous Development, Continuous Monitoring', 'Melakukan proses pemeliharaan konstruktif, dengan aktivitas minimal terdiri dari: 1) Melakukan pembahasan business requirement definition (user requirement) dengan unit kerja pemilik aplikasi. 2) Membuat mockup aplikasi yang diajukan untuk dikembangkan dan dibangun.. 3) Menyusun rencana kerja pengembangan dan pembangunan aplikasi yang diajukan. 4) Menyusun dokumentasi pengembangan dan pembangunan aplikasi. 5) Menyusun skenario pengujian aplikasi yang telah dikembangkan dan dibangun. 6) Melakukan pengujian aplikasi (functional test, integration test, user acceptance test, security test). 7) Melaksanakan pelatihan kepada pengguna aplikasi yang telah dikembangkan dan dibangun. 8) Menyusun dokumen manual penggunaan aplikasi yang telah dikembangkan dan dibangun.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2319960);
